test_suite:
const items = ['apple', 'banana', 'apricot', 'cherry'];
const filterFn = (item: string, q: string) => item.includes(q);

test('starts with empty query and all items', () => {
  const { result } = renderHook(() => useTransitionFilter(items, filterFn));
  expect(result.current.query).toBe('');
  expect(result.current.filtered).toEqual(items);
});

test('filtered updates after setQuery', () => {
  const { result } = renderHook(() => useTransitionFilter(items, filterFn));
  act(() => result.current.setQuery('ap'));
  expect(result.current.filtered).toEqual(['apple', 'apricot']);
});

test('empty string query returns all items', () => {
  const { result } = renderHook(() => useTransitionFilter(items, filterFn));
  act(() => result.current.setQuery('ban'));
  act(() => result.current.setQuery(''));
  expect(result.current.filtered).toEqual(items);
});

test('query state reflects setter value', () => {
  const { result } = renderHook(() => useTransitionFilter(items, filterFn));
  act(() => result.current.setQuery('cherry'));
  expect(result.current.query).toBe('cherry');
});

// __hidden__
test('returns isPending boolean', () => {
  const { result } = renderHook(() => useTransitionFilter(items, filterFn));
  expect(typeof result.current.isPending).toBe('boolean');
});

solution:
import { useState, useTransition, useMemo } from 'react';

export function useTransitionFilter<T>(
  items: T[],
  filterFn: (item: T, query: string) => boolean
) {
  const [query, setQueryRaw] = useState('');
  const [deferredQuery, setDeferredQuery] = useState('');
  const [isPending, startTransition] = useTransition();

  function setQuery(q: string) {
    setQueryRaw(q);
    startTransition(() => setDeferredQuery(q));
  }

  const filtered = useMemo(
    () => deferredQuery ? items.filter(item => filterFn(item, deferredQuery)) : items,
    [items, deferredQuery, filterFn]
  );

  return { query, setQuery, filtered, isPending };
}
